package net.officefloor.hq.app;

import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import org.springframework.context.annotation.Profile;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
 */
@Profile("harness")
@RestController
@RequestMapping("/__test__")
public class TestSupportController {

    private final Audit audit;
    private final JdbcTemplate jdbc;

    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
        this.audit = audit;
        this.jdbc = jdbc;
    }

    /**
     * Domain tables in FK-dependency order (child before parent). Referential integrity is dropped
     * around the truncates so the order is not load-bearing, but keeping it sensible documents the
     * shape. A new table joins the reset by being added to this list — no new statement to write.
     */
    private static final List<String> DOMAIN_TABLES =
            List.of("note", "project_tag", "tag", "payment", "line_item", "invoice", "task",
                    "contact", "project", "client", "app_setting");

    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
    @PostMapping("/reset")
    public void reset() {
        audit.clear();
        // Drop referential integrity around the truncates: RESTART IDENTITY on each, then restore
        // it. That makes the order above cosmetic and clears every FK-referenced table cleanly.
        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
        for (String table : DOMAIN_TABLES) {
            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
        }
        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
    }

    /**
     * Insert the fixture a spec needs; the payload shape evolves with the schema. Each table is one
     * {@link #seedRows} call: name the fixture key, then map a row to an INSERT. A new table is one
     * more call here — the null-check and per-row loop are shared, not repeated.
     */
    @PostMapping("/seed")
    public void seed(@RequestBody Map<String, Object> fixture) {
        seedRows(fixture, "clients", c -> jdbc.update(
                "INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
                asLong(c, "id"), c.get("name"), c.get("email")));

        seedRows(fixture, "projects", p -> jdbc.update(
                "INSERT INTO project (id, name, client_id, status, archived, budget) "
                        + "VALUES (?, ?, ?, ?, ?, ?)",
                asLong(p, "id"), p.get("name"), asLong(p, "clientId"),
                p.get("status") == null ? "ACTIVE" : p.get("status"),
                Boolean.TRUE.equals(p.get("archived")),
                p.get("budget") == null ? 0 : p.get("budget")));

        seedRows(fixture, "tasks", t -> jdbc.update(
                "INSERT INTO task (id, project_id, title, done) VALUES (?, ?, ?, ?)",
                asLong(t, "id"), asLong(t, "projectId"), t.get("title"),
                Boolean.TRUE.equals(t.get("done"))));

        seedRows(fixture, "tags", t -> jdbc.update(
                "INSERT INTO tag (id, name) VALUES (?, ?)",
                asLong(t, "id"), t.get("name")));

        // A project_tag row is a (project, tag) pairing with no id of its own in the fixture — let the
        // IDENTITY column assign one (GENERATED BY DEFAULT allows the omission).
        seedRows(fixture, "projectTags", pt -> jdbc.update(
                "INSERT INTO project_tag (project_id, tag_id) VALUES (?, ?)",
                asLong(pt, "projectId"), asLong(pt, "tagId")));

        seedRows(fixture, "notes", n -> jdbc.update(
                "INSERT INTO note (id, target_type, target_id, note_text, created_at) "
                        + "VALUES (?, ?, ?, ?, ?)",
                asLong(n, "id"), n.get("targetType"), asLong(n, "targetId"),
                n.get("text"), n.get("at")));
        // The seed inserts explicit ids into note's IDENTITY column (GENERATED BY DEFAULT), which does
        // not advance the identity sequence — reset RESTARTed it at 1. Without this the first app-side
        // save() would regenerate id=1 and collide with a seeded row. Advance it past the max seeded
        // id so a note added through the API (POST /api/notes) gets a fresh id.
        syncIdentity("note");

        seedRows(fixture, "contacts", c -> jdbc.update(
                "INSERT INTO contact (id, client_id, name, email, role, is_primary) "
                        + "VALUES (?, ?, ?, ?, ?, ?)",
                asLong(c, "id"), asLong(c, "clientId"),
                c.get("name"), c.get("email"), c.get("role"),
                Boolean.TRUE.equals(c.get("primary"))));
        syncIdentity("contact");

        // An invoice is now itemised: its amount is the sum of qty * unit price across its lines
        // (nested under the invoice in the fixture). The stored amount is the derived total — the
        // fixture may still supply an explicit "amount" for an invoice with no lines, otherwise it
        // is computed here so the invoice list reads the same total the lines add up to.
        seedRows(fixture, "invoices", i -> {
            List<Map<String, Object>> lines = asRows(i.get("lineItems"));
            double computed = 0;
            for (Map<String, Object> li : lines) {
                computed += ((Number) li.get("qty")).doubleValue()
                        * ((Number) li.get("unitPrice")).doubleValue();
            }
            Object explicit = i.get("amount");
            double amount = explicit == null ? computed : ((Number) explicit).doubleValue();
            // An optional percentage discount off the invoice's subtotal (0 when the fixture omits it).
            // The discount amount and the final total are derived from it (see InvoiceSummaryGet).
            Object discountPct = i.get("discountPct");
            jdbc.update(
                    "INSERT INTO invoice "
                            + "(id, project_id, amount, status, issued_date, due_date, discount_pct) "
                            + "VALUES (?, ?, ?, ?, ?, ?, ?)",
                    asLong(i, "id"), asLong(i, "projectId"), amount,
                    i.get("status") == null ? "UNPAID" : i.get("status"),
                    i.get("issuedDate"), i.get("dueDate"),
                    discountPct == null ? 0 : discountPct);
            for (Map<String, Object> li : lines) {
                jdbc.update(
                        "INSERT INTO line_item (id, invoice_id, description, qty, unit, unit_price) "
                                + "VALUES (?, ?, ?, ?, ?, ?)",
                        asLong(li, "id"), asLong(i, "id"), li.get("description"),
                        ((Number) li.get("qty")).intValue(),
                        li.get("unit") == null ? "unit" : li.get("unit"),
                        ((Number) li.get("unitPrice")).doubleValue());
            }
        });

        // A payment a client has made against an invoice: how much and on what day. Seeded at the
        // fixture's explicit id (GENERATED BY DEFAULT allows it); syncIdentity below advances the
        // sequence so an app-side save() (POST /api/payments) gets a fresh id.
        seedRows(fixture, "payments", p -> jdbc.update(
                "INSERT INTO payment (id, invoice_id, amount, paid_date) VALUES (?, ?, ?, ?)",
                asLong(p, "id"), asLong(p, "invoiceId"),
                ((Number) p.get("amount")).doubleValue(), p.get("date")));
        syncIdentity("payment");

        // A scalar top-level setting rather than a list of rows: the dashboard's "as of" reference
        // date, the fixed day overdue is measured against. Stored in the app_setting key/value table
        // so the dashboard reads a deterministic reference date.
        Object asOf = fixture.get("asOf");
        if (asOf != null) {
            jdbc.update("INSERT INTO app_setting (setting_key, setting_value) VALUES ('asOf', ?)",
                    asOf.toString());
        }
    }

    /** A nested optional list of rows (e.g. an invoice's line items), or empty when the key is absent. */
    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> asRows(Object value) {
        return value == null ? List.of() : (List<Map<String, Object>>) value;
    }

    /**
     * Run {@code insert} for each row under {@code key}, or do nothing if the fixture omits that key.
     * This is the shared "optional list of rows" shape every table seed follows.
     */
    @SuppressWarnings("unchecked")
    private void seedRows(Map<String, Object> fixture, String key,
            Consumer<Map<String, Object>> insert) {
        List<Map<String, Object>> rows = (List<Map<String, Object>>) fixture.get(key);
        if (rows == null) {
            return;
        }
        for (Map<String, Object> row : rows) {
            insert.accept(row);
        }
    }

    /**
     * Advance {@code table}'s IDENTITY sequence past its current max id, so app-side {@code save()}
     * calls that generate ids do not collide with rows the seed inserted at explicit ids.
     */
    private void syncIdentity(String table) {
        Long max = jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) FROM " + table, Long.class);
        if (max != null && max > 0) {
            jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH " + (max + 1));
        }
    }

    /** Read a JSON number field as a {@code long} (JSON integers arrive as {@link Number}). */
    private static long asLong(Map<String, Object> row, String key) {
        return ((Number) row.get(key)).longValue();
    }
}

