// An invoice's money summary as the server derives it: the subtotal (the sum of its line items), the
// percentage discount taken off it, the discount amount, the sales-tax percentage added on top after
// the discount, the tax amount, and the final total ((subtotal minus discount) times (1 plus the tax
// rate)). Derived server-side so the discount and tax are worked out in one place.
type InvoiceSummary = {
  subtotal: number;
  discountPct: number;
  discount: number;
  taxPct: number;
  tax: number;
  total: number;
};

